import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Flow } from 'flow-sdk';
import { GeneratedImage, MockupChip, SourceImage, Category, ModelType } from './types';
import { MOCKUP_PRESETS } from './constants';
import { generateMockup } from './services/ai';
import { ImageCard } from './components/ImageCard';

// Section Label Component from Spec
const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

export default function App() {
  const [sourceImage, setSourceImage] = useState<SourceImage | null>(null);
  const [feed, setFeed] = useState<GeneratedImage[]>([]);
  const [model, setModel] = useState<ModelType>('nano-banana');
  const [presets] = useState<MockupChip[]>(MOCKUP_PRESETS);

  const [showCustom, setShowCustom] = useState(false);
  const [customPromptValue, setCustomPromptValue] = useState('');
  const customInputRef = useRef<HTMLTextAreaElement>(null);

  // Inject Fonts and Global Design System CSS
  useEffect(() => {
    const fontId = 'google-fonts-design-system';
    if (!document.getElementById(fontId)) {
      const link = document.createElement('link');
      link.id = fontId;
      link.rel = 'stylesheet';
      link.href = 'https://fonts.googleapis.com/css2?family=Google+Sans:wght@400;500;600;700&family=Google+Sans+Flex:wght@400;500;600;700&family=Google+Sans+Text:wght@400;500;600;700&family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@20..48,100..700,0..1,-50..200&display=swap';
      document.head.appendChild(link);
    }

    const styleId = 'flow-design-system-css';
    if (!document.getElementById(styleId)) {
      const style = document.createElement('style');
      style.id = styleId;
      style.textContent = `
        .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
        .dark-scrollbar::-webkit-scrollbar { width: 6px; }
        .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
        .dark-scrollbar::-webkit-scrollbar-thumb:hover { background: #7a7a7a; }

        html, body, #root { 
          margin: 0; padding: 0; width: 100%; height: 100%; 
          background: #0e0e0e; 
          font-family: 'Google Sans Text', 'Google Sans', -apple-system, BlinkMacSystemFont, sans-serif;
          letter-spacing: 0.1px;
          -webkit-font-smoothing: antialiased;
        }

        @keyframes dropdown-enter {
          from { opacity: 0; transform: scale(0.95) translateY(-5px); }
          to   { opacity: 1; transform: scale(1) translateY(0); }
        }
        .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }
      `;
      document.head.appendChild(style);
    }
  }, []);

  const handleImportMedia = async () => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      if (media) {
        setSourceImage({
          id: media.mediaId,
          mediaId: media.mediaId,
          base64: media.base64,
          dataUrl: `data:${media.mimeType};base64,${media.base64}`,
          mimeType: media.mimeType
        });
      }
    } catch (e) {
      console.error("Failed to select media", e);
    }
  };

  const handleFireMockup = useCallback(async (prompt: string, label: string) => {
    if (!sourceImage || !sourceImage.mediaId) return;

    const id = crypto.randomUUID();
    const placeholder: GeneratedImage = {
      id,
      dataUrl: '',
      prompt: prompt.trim(),
      chipLabel: label,
      modelName: model === 'nano-banana-pro' ? 'Pro' : 'Fast',
      timestamp: Date.now(),
      status: 'loading'
    };

    setFeed(prev => [placeholder, ...prev]);

    try {
      const result = await generateMockup(prompt, { 
        base64: sourceImage.base64, 
        mediaId: sourceImage.mediaId 
      }, model);

      setFeed(prev => prev.map(img => 
        img.id === id 
          ? { ...img, dataUrl: result.dataUrl, base64: result.base64Image, status: 'ready' as const }
          : img
      ));
    } catch (error: any) {
      console.error("Mockup Generation Error:", error);
      setFeed(prev => prev.map(img => 
        img.id === id ? { ...img, status: 'error' as const } : img
      ));
    }
  }, [sourceImage, model]);

  const handleDelete = useCallback((id: string) => {
    setFeed(prev => prev.filter(item => item.id !== id));
  }, []);

  const handleCustomSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!customPromptValue.trim() || !sourceImage) return;

    const words = customPromptValue.trim().split(/\s+/);
    const preview = words.length > 6 
      ? words.slice(0, 6).join(' ') + '...' 
      : customPromptValue.trim();

    handleFireMockup(customPromptValue, `✨ custom: ${preview}`);
    setCustomPromptValue('');
  };

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] text-white overflow-hidden">

      {/* Panel (300px) - Flush against left edge */}
      <aside className="w-[300px] flex-shrink-0 border-r border-[rgba(218,220,224,0.15)] flex flex-col bg-transparent px-[10px] py-[12px]">

        <div className="flex flex-col gap-6 items-start w-full overflow-clip flex-1">
          {/* Source Management */}
          <div className="flex flex-col gap-2 w-full">
            <SectionLabel>Canvas media</SectionLabel>
            <section 
              className={`relative w-full aspect-video flex items-center justify-center rounded-xl border border-dashed transition-colors ${sourceImage ? 'border-transparent' : 'border-[#595959] bg-[#0e0e0e]'}`}
            >
              {sourceImage ? (
                <img src={sourceImage.dataUrl} className="w-full h-full object-contain" alt="Source" />
              ) : null}
            </section>

            {/* Action Button */}
            <div className="flex w-full">
              <button 
                onClick={handleImportMedia}
                className="flex-1 flex items-center justify-center gap-[2px] h-[34px] rounded-xl border border-[#595959] hover:bg-white/5 active:bg-white/10 text-[12px] font-medium text-white transition-all pl-[8px] pr-[16px] select-none"
              >
                <span className="material-symbols-outlined text-[18px] mr-1">grid_view</span>
                <span>Import Image</span>
              </button>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto w-full dark-scrollbar pr-1">
            <div className="flex flex-col gap-4">
              {/* Single staggered cluster of all chips */}
              <div className="flex flex-wrap gap-1.5 px-2">
                {presets.map((chip) => (
                  <button
                    key={chip.id}
                    onClick={() => handleFireMockup(chip.defaultPrompt, `${chip.emoji} ${chip.label}`)}
                    disabled={!sourceImage}
                    className={`flex items-center gap-2 px-3 py-1.5 transition-all rounded-full border border-[#595959] hover:border-[#7a7a7a] bg-transparent text-[11px] text-[rgba(218,220,224,0.9)] hover:text-white active:scale-[0.95] ${
                      !sourceImage ? 'opacity-30 cursor-not-allowed' : 'opacity-100'
                    }`}
                  >
                    <span className="text-[13px]">{chip.emoji}</span>
                    <span className="font-medium">{chip.label}</span>
                  </button>
                ))}

                {/* Custom Entry merged into the cluster area */}
                {!showCustom ? (
                  <button
                    onClick={() => setShowCustom(true)}
                    disabled={!sourceImage}
                    className={`flex items-center gap-2 px-3 py-1.5 transition-all rounded-full border border-dashed border-[#595959] hover:border-[#7a7a7a] bg-transparent text-[11px] text-[rgba(255,255,255,0.35)] hover:text-white ${
                      !sourceImage ? 'opacity-30 cursor-not-allowed' : 'opacity-100'
                    }`}
                  >
                    <span className="material-symbols-outlined text-[16px]">add</span>
                    <span className="font-medium">custom mockup</span>
                  </button>
                ) : (
                  <div className="w-full mt-2 animate-in slide-in-from-top-2 duration-200">
                    <div className="relative">
                      <textarea
                        ref={customInputRef}
                        autoFocus
                        value={customPromptValue}
                        onChange={(e) => setCustomPromptValue(e.target.value)}
                        placeholder="Describe your mockup ..."
                        className="border border-[#595959] hover:border-[#7a7a7a] focus:border-[#969696] rounded-xl w-full h-[80px] px-3 py-2.5 resize-none bg-transparent text-[11px] font-medium text-white placeholder-[rgba(218,220,224,0.5)] tracking-[0.1px] focus:outline-none transition-colors"
                        onKeyDown={(e) => {
                          if (e.key === 'Enter' && !e.shiftKey) {
                            e.preventDefault();
                            handleCustomSubmit();
                          }
                        }}
                      />
                      <button
                        onClick={() => handleCustomSubmit()}
                        disabled={!customPromptValue.trim()}
                        className="absolute bottom-3 right-3 text-[rgba(255,255,255,0.35)] hover:text-white disabled:opacity-0 transition-all"
                      >
                        <span className="material-symbols-outlined text-[18px]">send</span>
                      </button>
                    </div>
                    <button 
                      onClick={() => setShowCustom(false)}
                      className="text-[9px] text-[rgba(255,255,255,0.35)] hover:text-zinc-400 mt-1 uppercase font-medium"
                    >
                      Cancel
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Footer Actions */}
        <section className="flex flex-col gap-[5px] items-start w-full pt-4">
          <div className="flex w-full items-center border border-[#595959] rounded-xl overflow-hidden bg-transparent">
            <button
              onClick={() => setModel('nano-banana')}
              className={`flex-1 flex items-center justify-center h-[34px] rounded-xl text-[12px] font-medium tracking-[0.1px] transition-all cursor-pointer ${
                model === 'nano-banana' ? 'bg-[#969696] text-black' : 'text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5'
              }`}
            >
              Fast
            </button>
            <button
              onClick={() => setModel('nano-banana-pro')}
              className={`flex-1 flex items-center justify-center h-[34px] rounded-xl text-[12px] font-medium tracking-[0.1px] transition-all cursor-pointer ${
                model === 'nano-banana-pro' ? 'bg-[#969696] text-black' : 'text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5'
              }`}
            >
              Pro
            </button>
          </div>

          <button 
            onClick={() => { if(confirm('Clear session?')) { setSourceImage(null); setFeed([]); } }}
            className="w-full flex items-center justify-center gap-1.5 h-[34px] rounded-xl border border-[#595959] hover:bg-white/5 active:bg-white/10 text-[11px] font-medium text-[rgba(255,255,255,0.35)] transition-all uppercase tracking-[0.1px]"
          >
            <span className="material-symbols-outlined text-[16px]">restart_alt</span>
            Reset Session
          </button>
        </section>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto bg-[#0e0e0e] dark-scrollbar">
        <div className="max-w-3xl mx-auto p-12">
          {feed.length === 0 ? (
            <div className="h-[60vh] flex flex-col items-center justify-center text-[rgba(255,255,255,0.1)]">
              <p className="text-[12px] font-medium tracking-[0.2em] uppercase">Mockups will appear here</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 gap-16 pb-20">
              {feed.map((image) => (
                <ImageCard 
                  key={image.id} 
                  image={image} 
                  onReFire={() => handleFireMockup(image.prompt, image.chipLabel)}
                  onDelete={handleDelete}
                />
              ))}
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

import React, { useState } from 'react';
import { Flow } from 'flow-sdk';
import { GeneratedImage } from '../../types';

interface ImageCardProps {
  image: GeneratedImage;
  onReFire: (image: GeneratedImage) => void;
  onDelete: (id: string) => void;
}

export const ImageCard: React.FC<ImageCardProps> = ({ image, onReFire, onDelete }) => {
  const [showFullPrompt, setShowFullPrompt] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'loading' | 'done' | 'error'>('idle');

  const handleSaveToGallery = async () => {
    if (image.status !== 'ready' || !image.base64) return;

    setSaveStatus('loading');
    try {
      // Use Flow.save to add the mockup back to the Media Gallery
      // Note: Generative results are auto-saved by the SDK; this allows manual re-saving
      await Flow.save({
        base64: image.base64,
        mimeType: 'image/png',
        name: `Mockup: ${image.chipLabel}`
      });

      setSaveStatus('done');
      setTimeout(() => setSaveStatus('idle'), 2000);
    } catch (e) {
      console.error('Gallery save failed:', e);
      setSaveStatus('error');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }
  };

  const isLoading = image.status === 'loading';
  const isError = image.status === 'error';
  const isReady = image.status === 'ready';

  return (
    <div className="flex flex-col group">
      {/* Frame Container */}
      <div className="relative aspect-video border border-[rgba(218,220,224,0.15)] bg-[#0e0e0e] overflow-hidden mb-4 rounded-xl">
        {isLoading && (
          <div className="w-full h-full flex flex-col items-center justify-center bg-[#0e0e0e]">
             <span className="text-[48px] leading-none text-[rgba(255,255,255,0.2)] animate-pulse font-medium tracking-tighter">...</span>
             <span className="text-[10px] text-[rgba(255,255,255,0.2)] uppercase tracking-widest mt-2 font-medium">Generating Mockup</span>
          </div>
        )}

        {isReady && (
          <img 
            src={image.dataUrl} 
            alt={image.prompt} 
            className="w-full h-full object-cover"
          />
        )}

        {isError && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 text-center p-4">
             <span className="material-symbols-outlined text-red-400 text-[32px] mb-2">error</span>
             <span className="text-red-400 text-[11px] font-medium">Generation failed. Try again.</span>
          </div>
        )}
      </div>

      {/* Info & Actions Area */}
      <div className="flex flex-col gap-3 px-2">
        <div className="flex items-start justify-between">
          <div className="flex flex-col gap-0.5">
            <span className="text-[13px] font-medium text-white tracking-[0.1px]">
              {image.chipLabel}
            </span>
            <div className="flex items-center gap-2">
               <span className="text-[10px] text-[rgba(255,255,255,0.35)] font-bold uppercase tracking-widest">
                {image.modelName}
              </span>
            </div>
          </div>

          <div className="flex items-center gap-4 pt-1">
            <button 
              onClick={() => onReFire(image)}
              disabled={isLoading}
              title="Re-fire shot"
              className={`flex items-center justify-center transition-all ${isLoading ? 'opacity-20' : 'text-[rgba(255,255,255,0.35)] hover:text-white active:scale-90'}`}
            >
              <span className="material-symbols-outlined text-[20px]">refresh</span>
            </button>
            <button 
              onClick={handleSaveToGallery}
              disabled={isLoading || isError || saveStatus === 'loading'}
              title="Save to gallery"
              className={`flex items-center justify-center transition-all ${
                isLoading || isError 
                  ? 'opacity-20' 
                  : (saveStatus === 'done' 
                      ? 'text-green-400' 
                      : (saveStatus === 'error' ? 'text-red-400' : 'text-[rgba(255,255,255,0.35)] hover:text-white active:scale-90'))
              }`}
            >
              <span className={`material-symbols-outlined text-[20px] ${saveStatus === 'loading' ? 'animate-spin' : ''}`}>
                {saveStatus === 'loading' ? 'sync' : (saveStatus === 'done' ? 'done' : (saveStatus === 'error' ? 'error' : 'download'))}
              </span>
            </button>
            <button 
              onClick={() => onDelete(image.id)}
              disabled={isLoading}
              title="Delete mockup"
              className={`flex items-center justify-center transition-all ${isLoading ? 'opacity-20' : 'text-[rgba(255,255,255,0.35)] hover:text-red-400 active:scale-90'}`}
            >
              <span className="material-symbols-outlined text-[20px]">delete</span>
            </button>
            <button 
              onClick={() => setShowFullPrompt(!showFullPrompt)}
              className={`flex items-center justify-center transition-all ${showFullPrompt ? 'text-white' : 'text-[rgba(255,255,255,0.35)] hover:text-white active:scale-90'}`}
            >
              <span className="material-symbols-outlined text-[20px]">{showFullPrompt ? 'expand_less' : 'expand_more'}</span>
            </button>
          </div>
        </div>

        {showFullPrompt && (
          <div className="animate-in fade-in slide-in-from-top-1 duration-200 py-3 border-t border-[rgba(218,220,224,0.1)] mt-1">
            <p className="text-[rgba(255,255,255,0.35)] text-[11px] leading-relaxed">
              Prompt: {image.prompt}
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

import { Flow } from 'flow-sdk';
import { ModelType } from '../types';

export const generateMockup = async (
  prompt: string, 
  source: { base64: string, mediaId?: string }, 
  model: ModelType = 'nano-banana'
) => {
  // Map internal labels to Flow SDK model display names exactly as listed in the spec
  const modelDisplayName = model === 'nano-banana-pro' ? '🍌 Nano Banana Pro' : '🍌 Nano Banana 2';

  try {
    let mediaId = source.mediaId;

    // Safety check: In the new workflow, source.mediaId is guaranteed from Flow.media.select().
    if (!mediaId) {
      throw new Error("Missing mediaId: Please select an image from the Media Grid.");
    }

    const result = await Flow.generate.image({
      prompt: `${prompt}. Ensure the input image is placed directly and clearly onto the target surface with realistic perspective and lighting.`,
      referenceImageMediaIds: [mediaId],
      aspectRatio: '16:9',
      modelDisplayName
    });

    return { 
      base64Image: result.base64, 
      dataUrl: `data:${result.mimeType};base64,${result.base64}`,
      sourceMediaId: mediaId 
    };
  } catch (error) {
    console.error("Flow image generation failed:", error);
    throw error;
  }
};

export type Category = 'devices' | 'clothing' | 'print';

export type ModelType = 'nano-banana' | 'nano-banana-pro';

export interface GeneratedImage {
  id: string;
  dataUrl: string;
  base64?: string;
  prompt: string;
  chipLabel: string;
  modelName: string;
  timestamp: number;
  status: 'loading' | 'ready' | 'error';
}

export interface MockupChip {
  id: string;
  label: string;
  emoji: string;
  category: Category;
  defaultPrompt: string;
}

export interface SourceImage {
  id: string;
  base64: string;
  dataUrl: string;
  mimeType: string;
  mediaId?: string;
}

